/**
 * @name Command injection in subprocess calls
 * @description Using subprocess with untrusted input can lead to command injection
 * @kind path-problem
 * @problem.severity error
 * @id py/command-injection
 * @tags security
 *        external/cwe/cwe-078
 */

import python
import semmle.python.dataflow.new.DataFlow
import semmle.python.dataflow.new.TaintTracking
import semmle.python.dataflow.new.RemoteFlowSources
import semmle.python.Concepts
import semmle.python.ApiGraphs

module CommandInjectionConfig implements DataFlow::ConfigSig {
  predicate isSource(DataFlow::Node source) {
    source instanceof RemoteFlowSource
  }

  predicate isSink(DataFlow::Node sink) {
    // Find subprocess calls that execute commands
    exists(API::CallNode call |
      // subprocess.call, subprocess.run, subprocess.Popen, etc.
      (
        call = API::moduleImport("subprocess").getMember("call").getACall() or
        call = API::moduleImport("subprocess").getMember("run").getACall() or
        call = API::moduleImport("subprocess").getMember("Popen").getACall() or
        call = API::moduleImport("subprocess").getMember("check_call").getACall() or
        call = API::moduleImport("subprocess").getMember("check_output").getACall()
      ) and
      // The first argument is the command (shell=True changes behavior but still dangerous)
      sink = call.getArg(0)
    ) or
    // Also check for os.system and similar
    exists(API::CallNode call |
      call = API::moduleImport("os").getMember("system").getACall() and
      sink = call.getArg(0)
    )
  }
}

module CommandInjectionFlow = TaintTracking::Global<CommandInjectionConfig>;
import CommandInjectionFlow::PathGraph

from CommandInjectionFlow::PathNode source, CommandInjectionFlow::PathNode sink
where CommandInjectionFlow::flowPath(source, sink)
select sink.getNode(), source, sink, "Command injection from $@.", source.getNode(), "user input"

/**
 * @name Path traversal in file operations
 * @description Using untrusted input in file paths can lead to path traversal attacks
 * @kind path-problem
 * @problem.severity error
 * @id py/path-traversal
 * @tags security
 *        external/cwe/cwe-022
 */

import python
import semmle.python.dataflow.new.DataFlow
import semmle.python.dataflow.new.TaintTracking
import semmle.python.dataflow.new.RemoteFlowSources
import semmle.python.Concepts
import semmle.python.ApiGraphs

module PathTraversalConfig implements DataFlow::ConfigSig {
  predicate isSource(DataFlow::Node source) {
    source instanceof RemoteFlowSource
  }

  predicate isSink(DataFlow::Node sink) {
    // File open operations
    exists(API::CallNode call |
      call = API::builtin("open").getACall() and
      sink = call.getArg(0)
    ) or
    // os.path operations that could be dangerous
    exists(API::CallNode call |
      call = API::moduleImport("os").getMember(["remove", "unlink", "rmdir", "mkdir", "makedirs", "rename", "replace"]).getACall() and
      sink = call.getArg(0)
    ) or
    // pathlib operations
    exists(API::CallNode call |
      call = API::moduleImport("pathlib").getMember("Path").getACall() and
      sink = call.getArg(0)
    )
  }
}

module PathTraversalFlow = TaintTracking::Global<PathTraversalConfig>;
import PathTraversalFlow::PathGraph

from PathTraversalFlow::PathNode source, PathTraversalFlow::PathNode sink
where PathTraversalFlow::flowPath(source, sink)
select sink.getNode(), source, sink, "Path traversal vulnerability from $@.", source.getNode(), "user input"
